import numpy as np
from scipy.optimize import curve_fit, least_squares
rows=[]
for line in open('/app/graphene.dat', encoding='utf-8'):
    a,b=line.rstrip().split('\t')
    rows.append((float(a.replace(',','.')),float(b.replace(',','.'))))
a=np.array(rows); x=a[:,0]; y=a[:,1]
o=np.argsort(x); x=x[o]; y=y[o]

def lor(x,x0,gamma,amp,off):
    return off + amp*gamma**2/((x-x0)**2+gamma**2)

def lorlin(x,x0,gamma,amp,off,slope):
    return off+slope*(x-x0)+amp*gamma**2/((x-x0)**2+gamma**2)

def fit(lo,hi,p0=None, robust=False):
    m=(x>=lo)&(x<=hi); xx=x[m]; yy=y[m]
    if p0 is None:
      i=np.argmax(yy); off=np.percentile(yy,20); p0=[xx[i],(hi-lo)/10,max(yy[i]-off,1),off]
    bounds=([lo,1,0,-np.inf],[hi,hi-lo,np.inf,np.inf])
    if robust:
      sc=max(np.std(yy)*0.1,100)
      r=least_squares(lambda p:(lor(xx,*p)-yy), p0, bounds=bounds, loss='soft_l1', f_scale=sc, max_nfev=100000)
      p=r.x
    else:
      p,c=curve_fit(lor,xx,yy,p0=p0,bounds=bounds,maxfev=100000)
    pred=lor(xx,*p); rmse=np.sqrt(np.mean((yy-pred)**2)); r2=1-np.sum((yy-pred)**2)/np.sum((yy-yy.mean())**2)
    return len(xx),p,rmse,r2

def fitlin(lo,hi):
    m=(x>=lo)&(x<=hi); xx=x[m]; yy=y[m]
    i=np.argmax(yy); off=np.percentile(yy,20); p0=[xx[i],(hi-lo)/10,max(yy[i]-off,1),off,0]
    bounds=([lo,1,0,-np.inf,-np.inf],[hi,hi-lo,np.inf,np.inf,np.inf])
    p,c=curve_fit(lorlin,xx,yy,p0=p0,bounds=bounds,maxfev=200000)
    pred=lorlin(xx,*p); rmse=np.sqrt(np.mean((yy-pred)**2)); r2=1-np.sum((yy-pred)**2)/np.sum((yy-yy.mean())**2)
    return len(xx),p,rmse,r2

